-- Historical schema version 13 trigger, before the NULL-comparison fix.
CREATE TRIGGER IF NOT EXISTS agena_sessions_creation_failure_shape BEFORE UPDATE OF lifecycle_state, creation_failure_json ON agena_sessions WHEN (NEW.lifecycle_state = 'failed' AND (NEW.creation_failure_json IS NULL OR length(trim(NEW.creation_failure_json)) = 0 OR CASE WHEN json_valid(NEW.creation_failure_json) = 1 THEN (json_type(NEW.creation_failure_json, '$.id') != 'text' OR json_type(NEW.creation_failure_json, '$.code') != 'text' OR json_type(NEW.creation_failure_json, '$.user.fallback') != 'text') ELSE 1 END)) OR (NEW.lifecycle_state != 'failed' AND NEW.creation_failure_json IS NOT NULL) BEGIN SELECT RAISE(ABORT, 'creation failure must describe only failed sessions'); END;
